import unittest

class Test(unittest.TestCase):
    def test_initially_disconnected(self):
        uf = UnionFind(5)
        self.assertFalse(uf.connected(0, 1))
    def test_union_connects(self):
        uf = UnionFind(5)
        uf.union(0, 1)
        self.assertTrue(uf.connected(0, 1))
    def test_transitive_connection(self):
        uf = UnionFind(5)
        uf.union(0, 1)
        uf.union(1, 2)
        self.assertTrue(uf.connected(0, 2))
    def test_self_connected(self):
        uf = UnionFind(3)
        self.assertTrue(uf.connected(0, 0))

if __name__ == '__main__':
    unittest.main()
